@@ -167,33 +167,35 @@ public final class MultiFormatReader implements Reader {
   }

   private Result decodeInternal(BinaryBitmap image) throws NotFoundException {
-    if (readers != null) {
-      for (Reader reader : readers) {
-        if (Thread.currentThread().isInterrupted()) {
-          throw NotFoundException.getNotFoundInstance();
-        }
-        try {
-          return reader.decode(image, hints);
-        } catch (ReaderException re) {
-          // continue
-        }
-      }
-      if (hints != null && hints.containsKey(DecodeHintType.ALSO_INVERTED)) {
-        // Calling all readers again with inverted image
-        image.getBlackMatrix().flip();
-        for (Reader reader : readers) {
-          if (Thread.currentThread().isInterrupted()) {
-            throw NotFoundException.getNotFoundInstance();
-          }
-          try {
-            return reader.decode(image, hints);
-          } catch (ReaderException re) {
-            // continue
-          }
-        }
+    if (readers == null) {
+      throw NotFoundException.getNotFoundInstance();
+    }
+    Result result = tryAllReaders(image);
+    if (result != null) {
+      return result;
+    }
+    if (hints != null && hints.containsKey(DecodeHintType.ALSO_INVERTED)) {
+      image.getBlackMatrix().flip();
+      result = tryAllReaders(image);
+      if (result != null) {
+        return result;
       }
     }
     throw NotFoundException.getNotFoundInstance();
   }

+  private Result tryAllReaders(BinaryBitmap image) throws NotFoundException {
+    for (Reader reader : readers) {
+      if (Thread.currentThread().isInterrupted()) {
+        throw NotFoundException.getNotFoundInstance();
+      }
+      try {
+        return reader.decode(image, hints);
+      } catch (ReaderException re) {
+        // continue
+      }
+    }
+    return null;
+  }
+
 }
